const {JSDOM}=require('jsdom');
const fs=require('node:fs');
const assert=require('node:assert/strict');
const {test}=require('node:test');
const dir=require('node:path').join(__dirname,'..','extension');
const scripts=['vendor.katex.min.js','math-styles.js','formulas.js','formatting.js','adapter.js','renderer.js','native-popups.js','native-tools.js','attachments.js','composer.js'];
const turn=n=>`<div style="height:800px"><div data-turn-key="t${n}" data-content-search-turn-key="fallback-turn-${n}"><div data-talvt-turn-state="complete"><div><div data-sample="u${n}"><h4 data-conversation-role="user">你说</h4><div data-chatgpt-search-message-ids="u${n}">问题</div></div><div data-sample="a${n}"><div data-chatgpt-search-message-ids="a${n}"><h4 data-conversation-role="assistant">助手</h4><div data-markdown-text-style="assistant-message"><div data-dil-message-id="a${n}"><p>答案</p><div><p>数学说明</p><div class="katex"><span>公式</span></div><pre><code>const x = 1;</code></pre></div></div></div></div></div></div></div></div></div>`;
function setup(t,body=[1,2,3].map(turn).join(''),url='https://chatgpt.com/c/test'){
 const page=new JSDOM('<!doctype html><main>'+body+'</main><div data-composer-body><div contenteditable="true" role="textbox" data-composer-markdown></div><button aria-label="发送">发送</button></div>',{url,runScripts:'outside-only',pretendToBeVisual:true});
 t.after(()=>{page.window.GPTSmooth?.app?.stop();page.window.close();});const w=page.window;
 w.IntersectionObserver=class{constructor(cb){this.cb=cb;}observe(n){this.cb([{target:n,boundingClientRect:{height:100}}]);}unobserve(){}disconnect(){}};
 for(const script of scripts){const file=dir+'/'+script;if(fs.existsSync(file))w.eval(fs.readFileSync(file,'utf8'));}
 return {w,d:w.document,S:w.GPTSmooth};
}
test('detect actual new ChatGPT individual user and assistant messages',t=>{const{S,d}=setup(t);assert.ok(S?.Adapter,'adapter must be implemented');assert.deepEqual(Array.from(S.Adapter.messages(d),m=>m.id),['u1','a1','u2','a2','u3','a3']);});
test('detect legacy messages and ignore editor previews',t=>{const{S,d}=setup(t,'<article data-testid="conversation-turn-1"><div data-message-author-role="user">Hi</div></article><article data-testid="conversation-turn-2"><div data-message-author-role="assistant">Hello</div></article><form><div contenteditable="true" data-message-author-role="user">Draft</div></form>');assert.equal(S.Adapter.messages(d).length,2);});
test('chunking preserves whole formulas, tables and code blocks',t=>{const{S,d}=setup(t);const m=S.Adapter.messages(d)[1];const blocks=S.Adapter.blocks(m);assert.ok(blocks.some(n=>n.tagName==='PRE'));assert.ok(!blocks.some(n=>n.tagName==='CODE'||n.className==='katex'));});
test('render acceleration preserves message nodes and installs lazy rendering',t=>{const{S,d}=setup(t);const first=d.querySelector('[data-sample="a1"]');const r=new S.Renderer(d);r.refresh();assert.equal(first.isConnected,true);assert.ok(d.querySelectorAll('[data-smooth-chunk]').length>0);r.stop();assert.equal(d.querySelectorAll('[data-smooth-chunk]').length,0);});
test('manual prune keeps snapshot plus new messages until next prune',t=>{const{S,d}=setup(t);const r=new S.Renderer(d);r.refresh();r.prune(3);const shown=()=>S.Adapter.messages(d).filter(m=>!m.node.hasAttribute('data-smooth-hidden')).map(m=>m.id);assert.deepEqual(Array.from(shown()),['a2','u3','a3']);d.querySelector('main').insertAdjacentHTML('beforeend',turn(4));r.refresh();assert.deepEqual(Array.from(shown()),['a2','u3','a3','u4','a4']);r.prune(3);assert.deepEqual(Array.from(shown()),['a3','u4','a4']);r.showAll();assert.equal(shown().length,8);r.stop();});
test('restoring collapsed virtual rows preserves original height styles',t=>{const{S,d}=setup(t);const row=d.querySelector('[data-turn-key]').parentElement;const css=row.style.cssText;const r=new S.Renderer(d);r.prune(1);assert.ok(row.hasAttribute('data-smooth-collapsed'));r.stop();assert.equal(row.style.cssText,css);assert.ok(!row.hasAttribute('data-smooth-collapsed'));});
test('stop button is never treated as send',t=>{const{S,d}=setup(t);const b=d.querySelector('button');b.id='composer-submit-button';b.setAttribute('aria-label','停止生成');assert.equal(S.Adapter.sendButton(d,S.Adapter.editor(d)),null);});
test('writing a multiline native textarea dispatches one input transaction',async t=>{const{S,d}=setup(t);const old=d.querySelector('[contenteditable]');old.outerHTML='<textarea id="prompt-textarea"></textarea>';const editor=S.Adapter.editor(d);let inputs=0;editor.addEventListener('input',()=>inputs++);await S.Composer.write(editor,'第一行\n\n两个  空格');assert.equal(editor.value,'第一行\n\n两个  空格');assert.equal(inputs,1);});
test('send confirms acceptance before clearing its result',async t=>{const{S,d}=setup(t);d.querySelector('[contenteditable]').outerHTML='<textarea id="prompt-textarea"></textarea>';const editor=S.Adapter.editor(d);d.querySelector('button').onclick=()=>{editor.value='';};const result=await S.Composer.send(d,'你好','',{timeout:100});assert.equal(result.ok,true);});
test('native draft conflict prevents any replacement',async t=>{const{S,d}=setup(t);d.querySelector('[contenteditable]').textContent='别覆盖';const result=await S.Composer.send(d,'新草稿','',{timeout:100});assert.equal(result.ok,false);assert.equal(S.Adapter.text(S.Adapter.editor(d)),'别覆盖');});
test('unavailable send retains text in native editor',async t=>{const{S,d}=setup(t);d.querySelector('[contenteditable]').outerHTML='<textarea id="prompt-textarea"></textarea>';d.querySelector('button').disabled=true;const result=await S.Composer.send(d,'需要保留','',{timeout:60});assert.equal(result.ok,false);assert.equal(S.Adapter.text(S.Adapter.editor(d)),'需要保留');});
test('route change cancels deferred send without clicking',async t=>{const{S,w,d}=setup(t);d.querySelector('[contenteditable]').outerHTML='<textarea id="prompt-textarea"></textarea>';let clicks=0;const b=d.querySelector('button');b.disabled=true;b.onclick=()=>clicks++;const pending=S.Composer.send(d,'不跨对话发送','',{timeout:200});w.history.pushState({},'','/c/other');b.disabled=false;const result=await pending;assert.equal(result.ok,false);assert.equal(clicks,0);});

function full(t,body,url){const x=setup(t,body,url);for(const name of ['reader','history','ui','content']){const file=dir+'/'+name+'.js';if(fs.existsSync(file))x.w.eval(fs.readFileSync(file,'utf8'));}if(x.S.app?.tools)x.S.app.tools.popupTimeout=20;return x;}
const tick=ms=>new Promise(r=>setTimeout(r,ms));
test('typing in lightweight input never writes to native editor or rescans messages',async t=>{const{w,d,S}=full(t);await tick(40);assert.ok(d.getElementById('gpt-smooth-host'),'extension UI must mount');const area=d.getElementById('gpt-smooth-host').shadowRoot.querySelector('textarea');let inputs=0;d.querySelector('[contenteditable]').addEventListener('input',()=>inputs++);const scans=S.app.renderer.stats.scans;for(let i=0;i<50;i++){area.value+='中';area.dispatchEvent(new w.Event('input',{bubbles:true,composed:true}));}await tick(350);assert.equal(inputs,0);assert.equal(S.Adapter.text(S.Adapter.editor(d)),'');assert.equal(S.app.renderer.stats.scans,scans);});
test('IME Enter and Shift Enter do not send',async t=>{const{w,d}=full(t);await tick(40);const root=d.getElementById('gpt-smooth-host').shadowRoot;const area=root.querySelector('textarea');area.value='中文';area.dispatchEvent(new w.CompositionEvent('compositionstart'));area.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true,isComposing:true}));area.dispatchEvent(new w.CompositionEvent('compositionend'));area.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Enter',shiftKey:true,bubbles:true,cancelable:true}));assert.equal(d.querySelector('[contenteditable]').textContent,'');assert.equal(area.value,'中文');});
test('lightweight drafts are isolated when switching conversations',async t=>{const{w,d,S}=full(t);await tick(40);const area=d.getElementById('gpt-smooth-host').shadowRoot.querySelector('textarea');area.value='第一段对话的草稿';area.dispatchEvent(new w.Event('input'));w.history.pushState({},'','/c/another');S.app.checkRoute();assert.equal(area.value,'');area.value='第二段草稿';area.dispatchEvent(new w.Event('input'));w.history.pushState({},'','/c/test');S.app.checkRoute();assert.equal(area.value,'第一段对话的草稿');});
test('pause removes page rendering modifications',async t=>{const{d,S}=full(t);await tick(40);S.app.renderer.prune(1);await S.app.setEnabled(false);assert.equal(d.querySelectorAll('[data-smooth-hidden],[data-smooth-chunk],[data-smooth-collapsed]').length,0);});

test('new draft typed during send confirmation is not cleared',async t=>{const{S,d}=full(t);await tick(40);const ui=S.app.ui;ui.area.value='第一条';let resolve;S.Composer.send=()=>new Promise(r=>resolve=r);const pending=ui.send();ui.area.value='下一条草稿';resolve({ok:true});await pending;assert.equal(ui.area.value,'下一条草稿');});
test('sending immediately after route change never uses old conversation draft',async t=>{const{S,w}=full(t);await tick(40);S.app.ui.area.value='旧对话';let calls=0;S.Composer.send=async()=>{calls++;return {ok:true};};w.history.pushState({},'','/c/instant');await S.app.ui.send();assert.equal(calls,0);assert.equal(S.app.ui.area.value,'');});
test('repeating a failed send cannot overwrite a conflicting native draft',async t=>{const{S,d}=full(t);await tick(40);const ui=S.app.ui;ui.area.value='轻量草稿';d.querySelector('[contenteditable]').textContent='原生已有草稿';await ui.send();await ui.send();assert.equal(S.Adapter.text(S.Adapter.editor(d)),'原生已有草稿');assert.equal(ui.area.value,'轻量草稿');});
test('removed editor cannot confirm a successful send',async t=>{const{S,d}=setup(t);d.querySelector('[contenteditable]').outerHTML='<textarea id="prompt-textarea"></textarea>';d.querySelector('button').onclick=()=>S.Adapter.editor(d).remove();const result=await S.Composer.send(d,'保留我','',{timeout:80});assert.equal(result.ok,false);});
test('beforeunload also protects inactive conversation drafts',async t=>{const{S,w}=full(t);await tick(40);S.app.ui.area.value='旧对话草稿';w.history.pushState({},'','/c/new');S.app.checkRoute();const e=new w.Event('beforeunload',{cancelable:true});w.dispatchEvent(e);assert.equal(e.defaultPrevented,true);});
test('native handoff immediately after navigation never writes old draft',async t=>{const{S,w,d}=full(t);await tick(40);d.querySelector('[contenteditable]').outerHTML='<textarea id="prompt-textarea"></textarea>';S.app.ui.area.value='旧对话';w.history.pushState({},'','/c/instant');await S.app.ui.toggleNative();assert.equal(S.Adapter.text(S.Adapter.editor(d)),'');});
test('blank replacement editor does not confirm acceptance',async t=>{const{S,d}=setup(t);d.querySelector('[contenteditable]').outerHTML='<textarea id="prompt-textarea"></textarea>';d.querySelector('button').onclick=()=>S.Adapter.editor(d).outerHTML='<textarea id="prompt-textarea"></textarea>';const result=await S.Composer.send(d,'保留我','',{timeout:70});assert.equal(result.ok,false);});
test('stale send completion does not unlock another conversation send',async t=>{const{S,w,d}=full(t);await tick(40);const ui=S.app.ui;const resolves=[];S.Composer.send=()=>new Promise(r=>resolves.push(r));ui.area.value='A';const a=ui.send();w.history.pushState({},'','/c/b');S.app.checkRoute();d.querySelector('main').innerHTML=turn(9);ui.area.value='B';const b=ui.send();resolves[0]({ok:false,error:'cancelled'});await a;assert.equal(ui.pending,true);resolves[1]({ok:true});await b;});
test('revised draft can retry after extension-owned unavailable send',async t=>{const{S,d}=full(t);await tick(40);d.querySelector('[contenteditable]').outerHTML='<textarea id="prompt-textarea"></textarea>';const ui=S.app.ui;const originalSend=S.Composer.send;S.Composer.send=(doc,value,baseline,options)=>originalSend(doc,value,baseline,{...options,timeout:60});d.querySelector('button').disabled=true;ui.area.value='first';await ui.send();ui.area.value='revised';const button=d.querySelector('button');button.disabled=false;button.onclick=()=>{S.Adapter.editor(d).value='';};await ui.send();assert.equal(ui.area.value,'');});
test('reader shows last three messages and preserves later additions',async t=>{const{S,d}=full(t);await tick(40);S.app.reader.prune(3);const ids=()=>Array.from(S.app.reader.root.querySelectorAll('article'),n=>n.dataset.messageId);assert.deepEqual(ids(),['a2','u3','a3']);d.querySelector('main').insertAdjacentHTML('beforeend',turn(4));await tick(400);assert.deepEqual(ids(),['a2','u3','a3','u4','a4']);S.app.reader.prune(3);assert.deepEqual(ids(),['a3','u4','a4']);});
test('reader renders formulas by default without replacing them with TeX summaries',async t=>{const{S,d}=full(t);const target=d.querySelector('[data-sample="a3"] [data-markdown-text-style]');target.insertAdjacentHTML('beforeend','<p onclick="alert(1)"><span class="katex"><span class="katex-mathml"><math><mi>x</mi></math></span><span class="katex-html">duplicate</span></span><a href="javascript:alert(1)">link</a></p>');await tick(400);const root=S.app.reader.root;assert.equal(root.querySelectorAll('.katex-html,[onclick],[href^="javascript:"]').length,0);assert.equal(root.querySelectorAll('details.formula,summary').length,0);assert.ok(root.querySelector('math'));});
test('message edits arriving during the debounce window appear in reader',async t=>{const{S,d}=full(t);await tick(40);d.body.append(d.createElement('div'));await tick(20);d.querySelector('[data-sample="a3"] p').textContent='更新后的回答';await tick(400);assert.match(S.app.reader.root.querySelector('article[data-message-id="a3"]').textContent,/更新后的回答/);});
test('rendered formulas cannot reintroduce event handlers or unsafe URLs',async t=>{const{S,d}=full(t);d.querySelector('[data-sample="a3"] [data-markdown-text-style]').insertAdjacentHTML('beforeend','<span class="katex"><math onclick="alert(1)"><mi href="javascript:alert(1)">x</mi></math></span>');await tick(400);assert.ok(S.app.reader.root.querySelector('math'));assert.equal(S.app.reader.root.querySelectorAll('[onclick],[href^="javascript:"]').length,0);});
test('inline formulas stay inline while aligned tagged display formulas remain blocks',async t=>{const{S,d}=full(t);const area=d.querySelector('[data-sample="a3"] [data-markdown-text-style]');area.innerHTML='<p>当 <span class="katex"><math><mi>n</mi></math></span> 重变换。</p><span class="katex-display"><span class="katex"><math display="block"><mtable><mtr><mtd><mi>x</mi></mtd><mtd><mtext>(15)</mtext></mtd></mtr></mtable></math></span></span>';await tick(400);const body=S.app.reader.root.querySelector('article[data-message-id="a3"] .body');assert.ok(body.querySelector('p math:not([display="block"])'));assert.ok(body.querySelector('.formula math[display="block"]'));assert.equal(body.querySelectorAll('details').length,0);});
test('source text emphasis is preserved semantically after style isolation',async t=>{const{S,d}=full(t);d.querySelector('[data-sample="a3"] [data-markdown-text-style]').innerHTML='<p>问题：<span data-d-weight="bold">如何从已知解构造新的解。</span></p>';await tick(400);const text=S.app.reader.root.querySelector('.body .emphasis');assert.ok(text);assert.equal(text.textContent,'如何从已知解构造新的解。');});
test('sidebar layout reserves an input column without centering away useful text width',t=>{const{S,w,d}=setup(t);Object.defineProperty(w,'innerWidth',{value:1920});d.querySelector('main').getBoundingClientRect=()=>({left:340,width:1580,top:48});assert.ok(S.Adapter.layout,'shared layout must be implemented');const box=S.Adapter.layout(d,true);assert.equal(box.left,340);assert.equal(box.width,1580);assert.ok(box.rail>=320&&box.rail<=420);assert.equal(box.contentWidth,box.width-box.rail);assert.ok(box.contentWidth>1000);});
test('reader copy preserves paragraph boundaries',async t=>{const{S,w,d}=full(t);let copied='';Object.defineProperty(w.navigator,'clipboard',{value:{writeText:async text=>{copied=text;}}});d.querySelector('[data-sample="a3"] [data-markdown-text-style]').innerHTML='<p>第一段</p><p>第二段</p>';await tick(400);S.app.reader.root.querySelector('article[data-message-id="a3"] button').click();assert.equal(copied,'第一段\n\n第二段');});
test('authentication pages never receive extension overlays',t=>{const{w,d}=setup(t);w.history.pushState({},'','/auth/login');for(const n of ['reader','ui','content'])w.eval(fs.readFileSync(dir+'/'+n+'.js','utf8'));assert.equal(d.getElementById('gpt-smooth-reader'),null);assert.equal(d.getElementById('gpt-smooth-host'),null);});

test('aligned equation tags and matrix fractions render as MathML',t=>{const{S,d}=setup(t);assert.ok(S.Formulas,'formula adapter must be implemented');const node=S.Formulas.render(String.raw`\begin{aligned}S_t&=(S\times S_y+uS)_x\\u_x&=-S\cdot(S_x\times S_y)\end{aligned}\tag{2}`,true,d);assert.ok(node.querySelector('mtable'));assert.ok(node.querySelector('annotation').textContent.includes('tag{2}'));const matrix=S.Formulas.render(String.raw`\boxed{T_1=\begin{pmatrix}\lambda a_1+1&\lambda b_1\\\lambda c_1&\lambda d_1+1\end{pmatrix}}\tag{6}`,true,d);assert.ok(matrix.querySelector('mtable'));assert.equal(matrix.querySelector('math').getAttribute('display'),'block');});
test('repair source boxed formula with one missing closing brace before tag',t=>{const{S,d}=setup(t);const node=S.Formulas.render(String.raw`\boxed{T_1=\begin{pmatrix}a&b\\c&d\end{pmatrix}.\tag{6}`,true,d);assert.ok(node.querySelector('math'));assert.equal(node.querySelectorAll('.katex-error').length,0);assert.ok(node.querySelector('mtable'));});
test('raw source parse errors are repaired without evaluating trusted HTML macros',async t=>{const{S,d}=full(t);const source=d.querySelector('[data-sample="a3"] [data-markdown-text-style]');source.innerHTML=String.raw`<div data-d-component="math"><span class="katex-error">\boxed{T=\begin{pmatrix}a&amp;b\\c&amp;d\end{pmatrix}.\tag{6}</span></div>`;await tick(400);assert.ok(S.app.reader.root.querySelector('math[display="block"]'));assert.equal(S.app.reader.root.querySelectorAll('.katex-error').length,0);});

test('copy separates display equations from following prose without duplicate math',async t=>{const{S,w,d}=full(t);let copied='';Object.defineProperty(w.navigator,'clipboard',{value:{writeText:async text=>{copied=text;}}});const source=d.querySelector('[data-sample="a3"] [data-markdown-text-style]');source.innerHTML='<p>before</p><span class="katex-display"><span class="katex"><math display="block"><semantics><mi>x</mi><annotation encoding="application/x-tex">x=1</annotation></semantics></math></span></span><p>after</p>';await tick(400);S.app.reader.root.querySelector('article[data-message-id="a3"] button').click();assert.equal(copied,'before\n\nx=1\n\nafter');});

test('copy preserves intentional blank lines inside code',async t=>{const{S,w,d}=full(t);let copied='';Object.defineProperty(w.navigator,'clipboard',{value:{writeText:async text=>{copied=text;}}});d.querySelector('[data-sample="a3"] [data-markdown-text-style]').innerHTML='<p>code:</p><pre><code>first\n\n\nsecond</code></pre>';await tick(400);S.app.reader.root.querySelector('article[data-message-id="a3"] button').click();assert.equal(copied,'code:\n\nfirst\n\n\nsecond');});

test('native sidebar resizing keeps input and reader layout in sync',async t=>{const x=setup(t),{S,w,d}=x;let width=1024;const callbacks=[];d.querySelector('main').getBoundingClientRect=()=>({left:0,width,top:48});w.ResizeObserver=class{constructor(callback){callbacks.push(callback);}observe(){}disconnect(){}};for(const name of ['reader','ui','content'])w.eval(fs.readFileSync(dir+'/'+name+'.js','utf8'));await tick(40);const dock=S.app.ui.root.querySelector('.dock');assert.equal(dock.classList.contains('stacked'),false);width=700;callbacks.forEach(callback=>callback([]));assert.equal(dock.classList.contains('stacked'),true);assert.equal(S.app.reader.host.style.getPropertyValue('--smooth-rail'),'0px');});

test('new math span component remains inline and only block components become formulas',t=>{const{S,d}=setup(t);const node=d.createElement('div');node.innerHTML='<p>通过 <span data-d-component="math"><span class="katex"><math><semantics><mi>n</mi><annotation encoding="application/x-tex">n</annotation></semantics></math></span></span> 重变换</p><div data-d-component="math" data-d-block><span class="katex"><math display="block"><semantics><mi>x</mi><annotation encoding="application/x-tex">x=1</annotation></semantics></math></span></div>';S.Formulas.normalize(node,d);assert.equal(node.querySelectorAll('p .formula,p math[display="block"]').length,0);assert.ok(node.querySelector('p math[display="inline"]'));assert.ok(node.querySelector('div.formula math[display="block"]'));});

test('current conversation wins over cached hidden main for messages editor and width',t=>{const{S,d}=setup(t);const old=d.querySelector('main'),cache=d.createElement('section');old.before(cache);cache.style.display='none';cache.append(old);old.insertAdjacentHTML('beforeend','<textarea id="prompt-textarea">旧草稿</textarea>');const active=d.createElement('main');active.innerHTML=turn(9)+'<textarea id="prompt-textarea">当前草稿</textarea>';d.body.append(active);active.getBoundingClientRect=()=>({left:260,width:1300,top:48});assert.equal(S.Adapter.messages(d).length,2);assert.equal(S.Adapter.messages(d)[0].id,'u9');assert.equal(S.Adapter.editor(d).value,'当前草稿');assert.equal(S.Adapter.layout(d).left,260);});

test('new text semantics, dividers and legacy code blocks survive style isolation',async t=>{const{S,d}=full(t);d.querySelector('[data-sample="a3"] [data-markdown-text-style]').innerHTML='<p><span data-d-default-strong>加粗</span><span data-d-font-style="italic">斜体</span><span data-markdown-copy="inline-code">x.xlsx</span></p><div data-d-component="divider"></div><div><code class="CodeContent-abc whitespace-pre! block"><span>line1\n\nline2</span></code></div>';await tick(400);const body=S.app.reader.root.querySelector('article[data-message-id="a3"] .body');assert.ok(body.querySelector('.emphasis'));assert.ok(body.querySelector('.italic'));assert.ok(body.querySelector('.inline-code'));assert.ok(body.querySelector('hr'));assert.equal(body.querySelector('pre code').textContent,'line1\n\nline2');});

test('native component typography and grid layout are copied without position or active styles',async t=>{const{S,d}=full(t);d.querySelector('[data-sample="a3"] [data-markdown-text-style]').innerHTML='<div data-d-component="grid" style="display:grid;gap:12px;grid-template-columns:repeat(2,minmax(0,1fr));position:fixed;top:0"><div data-d-component="box" data-d-has-border style="display:flex;flex-direction:column;gap:8px;padding:12px;border:1px solid #ddd"><h2 data-d-component="title" style="font-size:18px;line-height:28px;margin-top:24px;font-weight:600">标题</h2></div><div>右列</div></div>';await tick(400);const body=S.app.reader.root.querySelector('article[data-message-id="a3"] .body'),grid=body.querySelector('.native-grid');assert.ok(grid);assert.equal(grid.style.gap,'12px');assert.match(grid.style.gridTemplateColumns,/repeat\(2/);assert.equal(grid.style.position,'');assert.equal(body.querySelector('h2').style.fontSize,'18px');assert.equal(body.querySelector('h2').style.fontWeight,'600');});

