if(fs.existsSync('work/project-snapshots'))for(const filename of fs.readdirSync('work/project-snapshots').filter(n=>n.endsWith('.json'))){
 test('real project format coverage: '+filename,t=>{
  const snapshot=JSON.parse(fs.readFileSync('work/project-snapshots/'+filename,'utf8'));
  const page=new JSDOM(snapshot.html);const markup=page.window.document.querySelector('main').innerHTML;page.window.close();
  const{S,d}=full(t,markup,snapshot.url);S.app.reader.showAll();const messages=S.Adapter.messages(d),root=S.app.reader.root;
  assert.equal(messages.length,snapshot.summary.messages,'all mounted messages must be recognized');
  for(const message of messages.filter(m=>m.role==='assistant')){
   const source=message.node.querySelector('[data-markdown-text-style="assistant-message"],.markdown,.prose')||message.node;
   const article=[...root.querySelectorAll('article')].find(n=>n.dataset.messageId===message.id),body=article.querySelector('.body');
   for(const tag of ['p','h1','h2','h3','ul','ol','li','table','blockquote'])assert.equal(body.querySelectorAll(tag).length,source.querySelectorAll(tag).length,tag+' structure must be preserved');
   assert.equal(body.querySelectorAll('hr').length,source.querySelectorAll('hr,[data-d-component="divider"]').length,'separators');
   for(const strong of source.querySelectorAll('[data-d-default-strong]'))assert.ok([...body.querySelectorAll('.emphasis')].some(n=>n.textContent===strong.textContent),'strong text must survive');
   const nativeMath=[...source.querySelectorAll('.katex math')];
   const inline=nativeMath.filter(n=>!n.closest('.katex-display,div[data-d-component="math"],[data-d-component="math"][data-d-block]')&&n.getAttribute('display')!=='block').length;
   assert.equal(body.querySelectorAll('math[display="inline"]').length,inline,'inline math must never become block math');
   const blocks=[...source.querySelectorAll('pre,code[class*="CodeContent-"]')].filter(n=>!n.parentElement.closest('pre'));
   assert.deepEqual([...body.querySelectorAll('pre')].map(n=>n.textContent),blocks.map(n=>n.textContent),'code whitespace must survive');
   assert.equal(body.querySelectorAll('script,iframe,object,embed,[onclick],[onload]').length,0);
  }
 });
}


function uploadFixture(d,w,{partial=false}={}){
 const main=d.querySelector('main'),composer=d.querySelector('[data-composer-body]');main.append(composer);
 composer.insertAdjacentHTML('afterbegin','<div data-composer-attachments hidden></div><input type="file" accept="image/*" multiple aria-label="添加照片">');
 w.DataTransfer=class{constructor(){this.files=[];this.items={add:f=>this.files.push(f)};}};
 const input=main.querySelector('input[type=file]');let files=[];Object.defineProperty(input,'files',{get:()=>files,set:v=>files=v});let uploads=0;
 input.onchange=()=>{uploads++;const region=composer.querySelector('[data-composer-attachments]');region.hidden=false;for(const f of partial?files.slice(0,1):files){const card=d.createElement('div');card.dataset.attachmentId='file-'+uploads+'-'+region.children.length;card.textContent=f.name;region.append(card);}};
 return {input,composer,region:composer.querySelector('[data-composer-attachments]'),uploads:()=>uploads};
}
