function readerGeometry(r){const scroll=r.root.querySelector('.scroll');let growth=0;Object.defineProperties(scroll,{clientHeight:{get:()=>500},scrollHeight:{get:()=>r.list.children.length*1000+growth}});scroll.getBoundingClientRect=()=>({top:50,bottom:550,height:500});const measure=()=>{for(const article of r.records.values())article.article.getBoundingClientRect=()=>{const index=[...r.list.children].indexOf(article.article),top=50+index*1000+(index>=2?growth:0)-scroll.scrollTop;return {top,bottom:top+1000,height:1000};};};measure();return {scroll,measure,grow:n=>growth=n};}
