test('directory buttons retain identity, selection and scroll anchor when earlier questions arrive',async t=>{const{S,d}=full(t);await S.app.reader.flushPending();const ui=S.app.ui,dir=ui.$('questions'),buttons=[...dir.children],target=buttons[1];dir.getBoundingClientRect=()=>({top:0,bottom:160,height:160});for(const b of buttons)b.getBoundingClientRect=()=>({top:[...dir.children].indexOf(b)*60-dir.scrollTop,bottom:([...dir.children].indexOf(b)+1)*60-dir.scrollTop,height:60});dir.scrollTop=75;target.click();const oldTop=target.getBoundingClientRect().top;d.querySelector('main').insertAdjacentHTML('afterbegin',turn(0));S.app.reader.refresh();ui.update();assert.equal([...dir.children].find(b=>b.dataset.messageId==='u2'),target);assert.equal(target.getAttribute('aria-current'),'true');assert.equal(target.getBoundingClientRect().top,oldTop);});
